package studio.solocamera;
import android.graphics.*;import android.text.*;import android.text.style.*;import java.util.*;import java.util.regex.*;
/** Timed, editable captions. Imported SRT timings are preserved; typed speech uses estimated word timing. */
final class EditorCaptionStyles {
 static final String[] NAMES={"Plain","Word highlight","Karaoke","Clean interview","Bold word"};
 private static final ThreadLocal<Integer> WORD=new ThreadLocal<>();
 static void apply(EditorProject.Clip c,int style){c.captionStyle=style;c.titleDesign=0;c.titleMotion=0;c.designLogo="";c.imageUri="";c.font="font:inter";c.bold=style!=3;c.textSize=style==4?86:54;c.textColor=-1;c.captionAccent=0xffffc857;c.alignment=1;c.backgroundEnabled=style==3;c.textBackground=0xcc101820;c.outline=style==3?0:2;c.outlineColor=0xff000000;c.textY=-.42;c.textX=0;c.textPlaced=true;c.textReveal=0;}
 static CharSequence text(EditorProject.Clip c){Integer at=WORD.get();if(at==null||c.captionStyle==0||c.captionStyle==3)return c.text;Matcher m=Pattern.compile("\\S+").matcher(c.text);SpannableString s=new SpannableString(c.text);int index=0;while(m.find()){if(c.captionStyle==4&&index==at)return m.group();if(c.captionStyle==1&&index==at||c.captionStyle==2&&index<=at)s.setSpan(new ForegroundColorSpan(c.captionAccent),m.start(),m.end(),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);index++;}return s;}
 static final class Animation {private final EditorProject.Clip c;private final int w,h,count;private int word=-1;private Bitmap bitmap;Animation(EditorProject.Clip c,int w,int h){this.c=c;this.w=w;this.h=h;count=Math.max(1,c.text.trim().split("\\s+").length);}Bitmap frame(long local,long duration){int next=c.captionStyle==3?0:(int)Math.min(count-1,Math.max(0,local)*count/Math.max(1,duration));if(bitmap==null||word!=next){word=next;if(bitmap!=null)bitmap.recycle();try{WORD.set(word);bitmap=EditorText.bitmap(c,w,h);}finally{WORD.remove();}}return bitmap;}void release(){if(bitmap!=null){bitmap.recycle();bitmap=null;}}}
 static ArrayList<EditorProject.Caption> typed(String script,long at,long duration,int style,int track){String[] words=script.trim().split("\\s+");if(words.length>1000)throw new IllegalArgumentException("Use up to 1,000 words at a time");ArrayList<EditorProject.Caption> out=new ArrayList<>();if(script.trim().isEmpty())return out;for(int i=0;i<words.length;i+=5){int end=Math.min(words.length,i+5);String text=String.join(" ",Arrays.copyOfRange(words,i,end));out.add(cue(text,at+duration*i/words.length,at+duration*end/words.length,style,track));}return out;}
 static EditorProject.Caption cue(String text,long at,long end,int style,int track){if(text.length()>300)throw new IllegalArgumentException("A caption cue exceeds 300 characters");EditorProject.Caption c=new EditorProject.Caption();c.type="Text";c.at=at;c.end=Math.max(at+200,end);c.track=track;c.style=new EditorProject.Clip("caption:typed","Caption",Math.max(200,c.end-c.at));c.style.text=text;apply(c.style,style);return c;}
 static ArrayList<EditorProject.Caption> srt(String input,long offset,int style,int track){ArrayList<EditorProject.Caption> out=new ArrayList<>();Pattern timing=Pattern.compile("(\\d{1,2}):(\\d{2}):(\\d{2})[,.](\\d{3})\\s*-->\\s*(\\d{1,2}):(\\d{2}):(\\d{2})[,.](\\d{3})[^\\n]*\\n([\\s\\S]*?)(?=\\n\\s*\\n|$)");Matcher m=timing.matcher(input.replace("\r","").trim());while(m.find()){long start=time(m,1),end=time(m,5);if(end<=start)throw new IllegalArgumentException("Caption end must follow its start");String text=m.group(9).replaceAll("<[^>]+>","").trim();if(!text.isEmpty())out.add(cue(text,offset+start,offset+end,style,track));if(out.size()>EditorProject.MAX_CLIPS)throw new IllegalArgumentException("Import up to 300 caption cues at a time");}if(out.isEmpty())throw new IllegalArgumentException("No valid SRT captions found");return out;}
 private static long time(Matcher m,int i){return Long.parseLong(m.group(i))*3600000+Long.parseLong(m.group(i+1))*60000+Long.parseLong(m.group(i+2))*1000+Long.parseLong(m.group(i+3));}
}
